const ACCESS_TOKEN_TTL_SECS: u64 = 2 * 60 * 60; // 2 hours
const REFRESH_TOKEN_TTL_SECS: u64 = 90 * 24 * 60 * 60; // 90 days

#[derive(Serialize)]
struct LegacyAccessClaims {
    scope: String,
    sub: String,
    aud: String,
    iat: u64,
    exp: u64,
}

