1	// pattern: Functional Core
2	
3	use common::{ApiError, ErrorCode};
4	use jsonwebtoken::{decode, encode, Algorithm, DecodingKey, EncodingKey, Header, Validation};
5	use serde::{Deserialize, Serialize};
6	
7	use crate::app::AppState;
8	
9	/// Scope embedded in the JWT `scope` claim.
10	#[derive(Debug, Clone, PartialEq, Eq)]
11	pub enum AuthScope {
12	    Access,
13	    Refresh,
14	    AppPass,
15	    AppPassPrivileged,
16	}
17	
18	impl AuthScope {
19	    /// Whether this is an access-level scope — a full-access token *or* an app-password
20	    /// token (privileged or not). Only [`AuthScope::Refresh`] is not access-level.
21	    ///
22	    /// Endpoints that merely read/act on behalf of the session (e.g. `getSession`) accept any
23	    /// access-level scope; account-management endpoints (create/revoke app passwords, change
24	    /// handle, deactivate) require full [`AuthScope::Access`] and reject app-password scopes.
25	    pub fn is_access(&self) -> bool {
26	        matches!(
27	            self,
28	            AuthScope::Access | AuthScope::AppPass | AuthScope::AppPassPrivileged
29	        )
30	    }
31	}
32	
33	/// The `scope` claim string for a full-access session token.
34	pub(crate) const SCOPE_ACCESS: &str = "com.atproto.access";
35	
36	/// The `scope` claim string for an app-password session, selected by privilege.
37	pub(crate) fn app_pass_scope(privileged: bool) -> &'static str {
38	    if privileged {
39	        "com.atproto.appPassPrivileged"
40	    } else {
41	        "com.atproto.appPass"
42	    }
43	}
44	
45	/// Claims decoded from the server-issued access/refresh JWT.
46	#[derive(Debug, Deserialize)]
47	pub(crate) struct AccessTokenClaims {
48	    /// Subject — the authenticated DID.
49	    pub sub: String,
50	    /// Scope string from the AT Protocol spec.
51	    pub scope: String,
52	    /// Confirmation claim — present on DPoP-bound tokens (RFC 9449 §4.3).
53	    pub cnf: Option<CnfClaim>,
54	    /// Agent registration id — present only on tokens derived from an auth.md agent
55	    /// `identity_assertion` (the jwt-bearer grant). Absent on ordinary session/OAuth tokens, so it
56	    /// both marks a token as agent-derived and ties it back to the `agent_identities` row for
57	    /// revocation and audit attribution.
58	    #[serde(default)]
59	    pub registration_id: Option<String>,
60	}
61	
62	/// `cnf` (confirmation) claim carrying the JWK thumbprint for DPoP binding.
63	#[derive(Debug, Deserialize)]
64	pub(crate) struct CnfClaim {
65	    /// JWK SHA-256 thumbprint (base64url, no padding) of the client's DPoP key.
66	    pub jkt: Option<String>,
67	}
68	
69	/// Peek at the JWT header's `typ` field without verifying the signature.
70	/// Returns the `typ` value in lowercase, or `None` if parsing fails.
71	pub fn peek_jwt_typ(token: &str) -> Option<String> {
72	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
73	
74	    let header_b64 = token.split('.').next()?;
75	    let header_bytes = URL_SAFE_NO_PAD.decode(header_b64).ok()?;
76	    let header: serde_json::Value = serde_json::from_slice(&header_bytes).ok()?;
77	    header["typ"].as_str().map(|s| s.to_ascii_lowercase())
78	}
79	
80	/// Dispatch to the correct verification function based on token type.
81	/// Uses `typ` header as algorithm discriminator to prevent algorithm confusion attacks.
82	pub fn verify_access_token(token: &str, state: &AppState) -> Result<AccessTokenClaims, ApiError> {
83	    if peek_jwt_typ(token).as_deref() == Some("at+jwt") {
84	        verify_es256_access_token(token, state)
85	    } else {
86	        verify_hs256_access_token(token, state)
87	    }
88	}
89	
90	/// Build a `DecodingKey` for this server's own ES256 OAuth signing key from its public JWK.
91	///
92	/// Shared by every verifier of a token this server signed with that key — the AT+JWT access-token
93	/// verifier below and the agent `identity_assertion` verifier in `routes/oauth_token.rs` — so the
94	/// JWK-parsing/error-handling shape lives in one place and can't drift between the two.
95	pub(crate) fn oauth_es256_decoding_key(state: &AppState) -> Result<DecodingKey, ApiError> {
96	    let invalid = || ApiError::new(ErrorCode::InvalidToken, "invalid token");
97	    let jwk: jsonwebtoken::jwk::Jwk = serde_json::from_value(
98	        state.oauth_signing_keypair.public_key_jwk.clone(),
99	    )
100	    .map_err(|_| {
101	        tracing::error!("failed to parse OAuth signing key JWK");
102	        invalid()
103	    })?;
104	    DecodingKey::from_jwk(&jwk).map_err(|e| {
105	        tracing::error!(error = %e, "failed to build ES256 DecodingKey from OAuth signing key JWK");
106	        invalid()
107	    })
108	}
109	
110	/// Verify ES256 AT+JWT tokens issued by the OAuth token endpoint.
111	pub fn verify_es256_access_token(
112	    token: &str,
113	    state: &AppState,
114	) -> Result<AccessTokenClaims, ApiError> {
115	    let invalid = || ApiError::new(ErrorCode::InvalidToken, "invalid token");
116	    let decoding_key = oauth_es256_decoding_key(state)?;
117	    let mut validation = Validation::new(Algorithm::ES256);
118	    validation.set_required_spec_claims(&["exp", "sub"]);
119	    validation.leeway = 0;
120	    validation.set_audience(&[state.config.public_url.as_str()]);
121	    decode::<AccessTokenClaims>(token, &decoding_key, &validation)
122	        .map(|data| data.claims)
123	        .map_err(|e| {
124	            use jsonwebtoken::errors::ErrorKind;
125	            match e.kind() {
126	                ErrorKind::ExpiredSignature => ApiError::new(ErrorCode::TokenExpired, "token has expired"),
127	                _ => {
128	                    tracing::debug!(error = %e, error_kind = ?e.kind(), "ES256 access token verification failed");
129	                    invalid()
130	                }
131	            }
132	        })
133	}
134	
135	/// Verify HS256 access/refresh JWT issued by this server (legacy tokens).
136	pub fn verify_hs256_access_token(
137	    token: &str,
138	    state: &AppState,
139	) -> Result<AccessTokenClaims, ApiError> {
140	    let decoding_key = DecodingKey::from_secret(&state.jwt_secret);
141	
142	    let mut validation = Validation::new(Algorithm::HS256);
143	    // Validate audience only when the server DID is configured.
144	    match state.config.server_did.as_deref() {
145	        Some(did) => validation.set_audience(&[did]),
146	        None => {
147	            validation.validate_aud = false;
148	            tracing::warn!(
149	                "server_did not configured; JWT audience validation is disabled — \
150	                 set server_did in config for production deployments"
151	            );
152	        }
153	    }
154	    // `sub` is required by AT Protocol but not in jsonwebtoken's default required set.
155	    validation.set_required_spec_claims(&["exp", "sub"]);
156	    // Zero leeway: tokens we issued ourselves need no clock-skew tolerance.
157	    validation.leeway = 0;
158	
159	    decode::<AccessTokenClaims>(token, &decoding_key, &validation)
160	        .map(|data| data.claims)
161	        .map_err(|e| {
162	            use jsonwebtoken::errors::ErrorKind;
163	            match e.kind() {
164	                ErrorKind::ExpiredSignature => {
165	                    ApiError::new(ErrorCode::TokenExpired, "token has expired")
166	                }
167	                _ => {
168	                    tracing::debug!(error = %e, error_kind = ?e.kind(), "access token verification failed");
169	                    ApiError::new(ErrorCode::InvalidToken, "invalid token")
170	                }
171	            }
172	        })
173	}
