69	/// Peek at the JWT header's `typ` field without verifying the signature.
70	/// Returns the `typ` value in lowercase, or `None` if parsing fails.
71	pub fn peek_jwt_typ(token: &str) -> Option<String> {
72	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
73	
74	    let header_b64 = token.split('.').next()?;
75	    let header_bytes = URL_SAFE_NO_PAD.decode(header_b64).ok()?;
76	    let header: serde_json::Value = serde_json::from_slice(&header_bytes).ok()?;
77	    header["typ"].as_str().map(|s| s.to_ascii_lowercase())
78	}
