80	/// Peek at the JWT payload's `iss` claim without verifying the signature.
81	///
82	/// Returns the issuer string, or `None` if parsing fails or the claim is absent. Used to
83	/// discriminate an inbound atproto **service-auth** JWT — whose `iss` is the issuing account's DID
84	/// — from a server-issued session/OAuth access token (a legacy HS256 token carries no `iss`; an
85	/// OAuth `at+jwt` token's `iss` is this server's URL, never a `did:`). The value is untrusted until
86	/// the signature is verified against the resolved `#atproto` key; it only decides which auth path a
87	/// route takes.
88	pub fn peek_jwt_iss(token: &str) -> Option<String> {
89	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
90	
91	    let payload_b64 = token.split('.').nth(1)?;
92	    let payload_bytes = URL_SAFE_NO_PAD.decode(payload_b64).ok()?;
93	    let payload: serde_json::Value = serde_json::from_slice(&payload_bytes).ok()?;
94	    payload["iss"].as_str().map(str::to_string)
95	}
